void sc_format_path(const char *str, sc_path_t *path)
{
        int type = SC_PATH_TYPE_PATH;

        if (path) {
                memset(path, 0, sizeof(*path));
                if (*str == 'i' || *str == 'I') {
                        type = SC_PATH_TYPE_FILE_ID;
                        str++;
                }
                path->len = sizeof(path->value);
                if (sc_hex_to_bin(str, path->value, &path->len) >= 0) {
                        path->type = type;
                }
                path->count = -1;
        }
}

int sc_append_path(sc_path_t *dest, const sc_path_t *src)
{
        return sc_concatenate_path(dest, dest, src);
}

int sc_append_path_id(sc_path_t *dest, const u8 *id, size_t idlen)
{
        if (dest->len + idlen > SC_MAX_PATH_SIZE)
                return SC_ERROR_INVALID_ARGUMENTS;
        memcpy(dest->value + dest->len, id, idlen);
        dest->len += idlen;
        return SC_SUCCESS;
}

static int idprime_get_token_name(sc_card_t* card, char** tname)
{
        idprime_private_data_t * priv = card->drv_data;
        sc_path_t tinfo_path = {"\x00\x00", 2, 0, 0, SC_PATH_TYPE_PATH, {"", 0}};
        sc_file_t *file = NULL;
        u8 buf[2];
        int r;

        LOG_FUNC_CALLED(card->ctx);

        if (tname == NULL) {
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_INVALID_ARGUMENTS);
        }

        if (!priv->tinfo_present) {
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
        }

        memcpy(tinfo_path.value, priv->tinfo_df, 2);
        r = iso_ops->select_file(card, &tinfo_path, &file);
        if (r != SC_SUCCESS || file->size == 0) {
                sc_file_free(file);
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_NOT_SUPPORTED);
        }

        /* First two bytes lists 0x01, the second indicates length */
        r = iso_ops->read_binary(card, 0, buf, 2, 0);
        if (r < 2 || buf[1] > file->size) { /* make sure we do not overrun */
                sc_file_free(file);
                LOG_FUNC_RETURN(card->ctx, r);
        }
        sc_file_free(file);

        *tname = malloc(buf[1]);
        if (*tname == NULL) {
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_OUT_OF_MEMORY);
        }

        r = iso_ops->read_binary(card, 2, (unsigned char *)*tname, buf[1], 0);
        if (r < 1) {
                free(*tname);
                LOG_FUNC_RETURN(card->ctx, r);
        }

        if ((*tname)[r-1] != '\0') {
                (*tname)[r-1] = '\0';
        }
        LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
}

